def countBattleships(board: list[list[str]]) -> int:
    if not board or not board[0]:
        return 0

    rows, cols = len(board), len(board[0])
    count = 0

    for i in range(rows):
        for j in range(cols):
            # Check if current cell is the start of a battleship
            # A battleship starts when we find an 'X' that is not preceded by another 'X'
            # either from above or from left (i.e., it's the top-leftmost part)
            if board[i][j] == 'X':
                # Check if this cell is the start of a new battleship
                # It's the start if there's no 'X' to its left AND no 'X' above it
                is_start = True

                # If we're not at the first column, check for an 'X' to the left
                if j > 0 and board[i][j-1] == 'X':
                    is_start = False

                # If we're not at the first row, check for an 'X' above
                if i > 0 and board[i-1][j] == 'X':
                    is_start = False

                if is_start:
                    count += 1

    return count
